import{d as e}from"./card-CPvKk3Ty.js";var t={getReferralAgents(t){return e.get(`/users/referral-agents`,{params:{search:t}})},async getCounselors(){return(await e.get(`/users`,{params:{role:`COUNSELOR`}})||[]).map(e=>({id:e.id,name:`${e.firstName} ${e.lastName}`.trim(),email:e.email,role:e.role,status:e.status,branchId:e.branchId??null}))},getUsersByRole(t){return e.get(`/users`,{params:{role:t}})},updateUserStatus(t,n){return e.patch(`/users/${t}/status`,{status:n})},updateUserRole(t,n){return e.patch(`/users/${t}/role`,{role:n.toUpperCase()})},updateUserBranch(t,n){return e.patch(`/users/${t}/branch`,{branchId:n})},updateUserProfile(t,n){return e.patch(`/users/${t}`,n)},getBranches(){return e.get(`/users/branches`)}};export{t};